func atomic_wait32[T uint32 | uint64](mem []byte, addr T, exp uint32, timeout int64, waiters *sync.Map) int32 {
	if big {
		exp = bits.ReverseBytes32(exp)
	}
	ptr := atomic_ptr32(mem, addr)
	return atomic_wait(int64(addr), timeout, waiters, func() bool {
		return exp == atomic.LoadUint32(ptr)
	})
}

func atomic_wait(addr, timeout int64, waiters *sync.Map, equal func() bool) int32 {
	const (
		ok        = 0
		not_equal = 1
		timed_out = 2
	)

	if waiters == nil {
		panic("expected shared memory")
	}
	if timeout == 0 {
		if !equal() {
			return not_equal
		}
		return timed_out
	}

	wa, loaded := waiters.Load(addr)
	if !loaded {
		wa, _ = waiters.LoadOrStore(addr, &atomic_waiters{})
	}
	w := wa.(*atomic_waiters)
	w.Lock()

	switch {
	case !equal():
		w.Unlock()
		return not_equal
	case w.C == nil:
		w.C = make(chan struct{}, min(math.MaxInt, math.MaxUint32))
	case w.N >= cap(w.C):
		w.Unlock()
		panic("too many waiters")
	}

	wait := w.C
	w.N++
	w.Unlock()

	if timeout < 0 {
		<-wait
		return ok
	}

	timer := time.NewTimer(time.Duration(timeout))
	select {
	case <-wait:
		timer.Stop()
		return ok
	case <-timer.C:
	}

	w.Lock()
	if w.N > 0 {
		w.N--
		w.Unlock()
		return timed_out
	}
	<-wait
	w.Unlock()
	return ok
}

